	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/blog-posts/{id}/unpublish", wrapper.UnpublishBlogPost)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/products", wrapper.ListProducts)
